// Genuine raster-only scan with legible words and no PDF text objects. Generated with Pillow and pypdf.
export function imageDocument() { return Buffer.from('', 'base64') }
// A standard password-protected PDF containing the embedded text synthetic-plinth-protected-9101.
export const protectedDocument = Buffer.from('', 'base64')
// An actual Word package: the supplied words are in its compressed main document XML.
export const unsupportedDocument = Buffer.from('', 'base64')
export const png = Buffer.from('', 'base64')
